    {
		Lifespan zeroOn = Lifespan.nowOn(0);
		if (CommonSet.READ.kinds().equals(expectedKinds)) {
			Map<string, object> args = rmiMethodSetReadBreak.expect();
			addBreakpointAndLoc(tb.trace.getObjectManager(), zeroOn, tb.range(dynOffset),
